from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

STATUSES = {"SUCCESS", "FAILED", "PENDING"}


def parse_ts(raw):
    """Parse timestamp (epoch or ISO-8601), return timezone-aware UTC datetime."""
    raw = raw.strip()
    # Try epoch number first
