    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        raise ValueError("Invalid timestamp")


def parse_amount(raw):
    """Parse monetary amount string, removing currency symbols and commas."""
    raw = raw.strip()
    # Remove currency symbols and commas, keep digits, ., -, +
    cleaned = re.sub(r'[^0-9.\-+]', '', raw)
    if not cleaned:
        raise InvalidOperation()
    return Decimal(cleaned)


def load_rows(path):
    """Read well-formed rows; malformed rows are skipped."""
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                tx_id_raw = row.get("tx_id")
                ts_raw = row.get("timestamp")
                amount_raw = row.get("amount")
                status_raw = row.get("status")

                if not tx_id_raw or not ts_raw or not amount_raw or not status_raw:
                    continue

                tx_id = tx_id_raw.strip()
                if not tx_id:
                    continue

                ts = parse_ts(ts_raw)
                amount = parse_amount(amount_raw)
                status = status_raw.strip().upper()

                if status not in STATUSES:
                    continue
                if not amount.is_finite():
                    continue

                rows.append({
                    "tx_id_orig": tx_id,
                    "tx_id_key": tx_id.lower(),
                    "ts": ts,
                    "amount": amount,
                    "status": status,
                })
            except (KeyError, AttributeError, ValueError, InvalidOperation):
                continue
    return rows


def rank(r):
    """
    Return tuple for ranking:
    1. Kind: Final (SUCCESS/FAILED) = 1, Provisional (PENDING) = 0
    2. Timestamp: absolute point in time (dt)
    """
    is_final = 1 if r["status"] in ("SUCCESS", "FAILED") else 0
    return (is_final, r["ts"])


def dedupe(rows):
    """Keep one record per tx_id_key (ties: later row in file wins via >=)."""
    best = {}
    for r in rows:
        key = r["tx_id_key"]
        cur = best.get(key)
        if cur is None or rank(r) >= rank(cur):
            best[key] = r
    return list(best.values())


def summarize(rows):
    total = Decimal("0.00")
    valid = 0
    failed = 0
    for r in dedupe(rows):
        if r["status"] == "SUCCESS":
            valid += 1
            rounded = r["amount"].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            total += rounded
        elif r["status"] == "FAILED":
            failed += 1
        elif r["status"] == "PENDING":
            pass

    return {
        "total_valid_amount": float(total),
        "valid_count": valid,
        "failed_count": failed,
    }


def main():
    if len(sys.argv) != 2:
        print("usage: python3 reconcile.py <transactions.csv>", file=sys.stderr)
        sys.exit(2)
    try:
        rows = load_rows(sys.argv[1])
        print(json.dumps(summarize(rows)))
    except Exception as e:
        print(f"usage: python3 reconcile.py <transactions.csv>", file=sys.stderr)
        sys.exit(2)


if __name__ == "__main__":
    main()
